-- C10-A056 pipeline: leads, enquiries, opportunities, versioned quotations, follow-ups, order adapter, tickets, finance boundary.
DO $g$ BEGIN IF to_regclass('c10_demo.a056_customers') IS NULL THEN RAISE EXCEPTION 'A056_CORE_REQUIRED'; END IF; END $g$;

CREATE TABLE c10_demo.a056_leads(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint,
 source text NOT NULL CHECK(length(source) BETWEEN 1 AND 60), name text, email text, phone text, email_norm text, phone_norm text, note text,
 customer_id bigint, status text NOT NULL DEFAULT 'new' CHECK(status IN('new','qualified','disqualified','converted')), reason text,
 version bigint NOT NULL DEFAULT 1, request_key text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(business_id,request_key), UNIQUE(id,tenant_id,business_id),
 FOREIGN KEY(business_id,tenant_id) REFERENCES c10_demo.businesses(id,tenant_id),
 FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_intake_endpoints(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint,
 channel text NOT NULL CHECK(channel IN('website','ecommerce','pos','offline','phone')), label text NOT NULL, token_hash text NOT NULL UNIQUE,
 rate_limit_per_hour int NOT NULL CHECK(rate_limit_per_hour BETWEEN 1 AND 10000), status text NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked')),
 request_key text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,request_key), UNIQUE(id,tenant_id,business_id),
 FOREIGN KEY(business_id,tenant_id) REFERENCES c10_demo.businesses(id,tenant_id),
 FOREIGN KEY(site_id,tenant_id,business_id) REFERENCES c10_demo.sites(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_enquiries(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint,
 channel text NOT NULL CHECK(channel IN('website','ecommerce','pos','offline','phone','email','staff')),
 intent text NOT NULL DEFAULT 'enquiry' CHECK(intent IN('enquiry','quote_request','order_request')),
 subject text, body text, contact_name text, contact_email text, contact_phone text, payload jsonb NOT NULL DEFAULT '{}',
 customer_id bigint, lead_id bigint, endpoint_id bigint, reference text NOT NULL UNIQUE,
 status text NOT NULL DEFAULT 'RECEIVED' CHECK(status IN('RECEIVED','DRAFT','triaged','converted','closed')),
 version bigint NOT NULL DEFAULT 1, request_key text NOT NULL, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(business_id,request_key),
 FOREIGN KEY(business_id,tenant_id) REFERENCES c10_demo.businesses(id,tenant_id),
 FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id),
 FOREIGN KEY(lead_id,tenant_id,business_id) REFERENCES c10_demo.a056_leads(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_intake_log(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, endpoint_id bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX a056_intake_log_e ON c10_demo.a056_intake_log(endpoint_id,created_at);
CREATE TABLE c10_demo.a056_opportunities(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint,
 customer_id bigint NOT NULL, lead_id bigint, enquiry_id bigint, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),
 stage_code text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN('open','won','lost')),
 expected_value numeric(18,2) CHECK(expected_value IS NULL OR (expected_value>=0 AND expected_value<=100000000)), currency text NOT NULL DEFAULT 'BDT' CHECK(currency='BDT'),
 expected_close date, owner_user uuid, version bigint NOT NULL DEFAULT 1, request_key text NOT NULL, created_by uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz,
 UNIQUE(business_id,request_key), UNIQUE(id,tenant_id,business_id),
 FOREIGN KEY(business_id,tenant_id) REFERENCES c10_demo.businesses(id,tenant_id),
 FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id));
CREATE INDEX a056_opp_b ON c10_demo.a056_opportunities(business_id,status,stage_code);
CREATE TABLE c10_demo.a056_opp_stage_log(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, opportunity_id bigint NOT NULL,
 from_stage text, to_stage text NOT NULL, actor uuid NOT NULL, reason text, request_key text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,request_key));
CREATE TABLE c10_demo.a056_quotations(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint,
 opportunity_id bigint NOT NULL, customer_id bigint NOT NULL, quote_no text, current_version int NOT NULL DEFAULT 1,
 version bigint NOT NULL DEFAULT 1, request_key text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(business_id,request_key), UNIQUE(id,tenant_id,business_id),
 FOREIGN KEY(opportunity_id,tenant_id,business_id) REFERENCES c10_demo.a056_opportunities(id,tenant_id,business_id),
 FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_quote_versions(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, quotation_id bigint NOT NULL, version_no int NOT NULL,
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','pending_approval','approved','rejected','sent','accepted','declined','superseded','converted')),
 total numeric(18,2) NOT NULL, max_discount_pct numeric(5,2) NOT NULL, requires_approval boolean NOT NULL, valid_until date, notes text,
 created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), decided_by uuid, decided_at timestamptz, decision_note text,
 UNIQUE(quotation_id,version_no), UNIQUE(id,tenant_id,business_id),
 FOREIGN KEY(quotation_id,tenant_id,business_id) REFERENCES c10_demo.a056_quotations(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_quote_lines(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, version_id bigint NOT NULL, line_no int NOT NULL,
 description text NOT NULL, item_id bigint, quantity numeric(15,3) NOT NULL CHECK(quantity>0), unit_price numeric(18,2) NOT NULL CHECK(unit_price>=0),
 discount_pct numeric(5,2) NOT NULL DEFAULT 0 CHECK(discount_pct BETWEEN 0 AND 100), line_total numeric(18,2) NOT NULL, UNIQUE(version_id,line_no),
 FOREIGN KEY(version_id,tenant_id,business_id) REFERENCES c10_demo.a056_quote_versions(id,tenant_id,business_id));
CREATE FUNCTION c10_demo.a056_lines_frozen() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN RAISE EXCEPTION 'A056_QUOTE_LINES_IMMUTABLE'; END $f$;
CREATE TRIGGER a056_lines_frozen BEFORE UPDATE OR DELETE ON c10_demo.a056_quote_lines FOR EACH ROW EXECUTE FUNCTION c10_demo.a056_lines_frozen();
CREATE TABLE c10_demo.a056_order_links(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint, customer_id bigint NOT NULL,
 quotation_id bigint NOT NULL, version_no int NOT NULL, line_no int NOT NULL, a049_order_id bigint UNIQUE,
 adapter text NOT NULL CHECK(adapter IN('A049_CANONICAL','TEST_ADAPTER')), quantity numeric(15,3) NOT NULL, net_unit_price numeric(18,2) NOT NULL,
 request_key text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(quotation_id,version_no,line_no), UNIQUE(business_id,request_key,line_no),
 CHECK((adapter='A049_CANONICAL' AND a049_order_id IS NOT NULL) OR (adapter='TEST_ADAPTER' AND a049_order_id IS NULL)),
 FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id),
 FOREIGN KEY(quotation_id,tenant_id,business_id) REFERENCES c10_demo.a056_quotations(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_followups(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint, customer_id bigint NOT NULL,
 opportunity_id bigint, ticket_id bigint, due_at timestamptz NOT NULL, note text, assignee uuid, status text NOT NULL DEFAULT 'open' CHECK(status IN('open','done','cancelled')),
 outcome_note text, completed_at timestamptz, version bigint NOT NULL DEFAULT 1, request_key text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(business_id,request_key), FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id));
CREATE INDEX a056_fu_b ON c10_demo.a056_followups(business_id,status,due_at);
CREATE TABLE c10_demo.a056_tickets(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, site_id bigint, customer_id bigint NOT NULL, order_link_id bigint,
 kind text NOT NULL CHECK(kind IN('complaint','service','warranty','return_request')), priority text NOT NULL CHECK(priority IN('urgent','standard','low')),
 subject text NOT NULL, description text, status text NOT NULL DEFAULT 'open' CHECK(status IN('open','assigned','in_progress','waiting_customer','resolved','closed')),
 assignee uuid, sla_hours int NOT NULL, sla_due_at timestamptz NOT NULL, first_response_at timestamptz, resolved_at timestamptz, closed_at timestamptz,
 resolution_note text, resolution_evidence text, reopen_count int NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 1, request_key text NOT NULL, created_by uuid NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,request_key),
 FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_ticket_events(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, ticket_id bigint NOT NULL REFERENCES c10_demo.a056_tickets(id),
 event text NOT NULL, actor uuid NOT NULL, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE c10_demo.a056_finance_sources(
 business_id bigint PRIMARY KEY, tenant_id bigint NOT NULL, read_fn text NOT NULL, certification_ref text, certified boolean NOT NULL DEFAULT false,
 version bigint NOT NULL DEFAULT 1, changed_by uuid NOT NULL, changed_at timestamptz NOT NULL DEFAULT now(),
 FOREIGN KEY(business_id,tenant_id) REFERENCES c10_demo.businesses(id,tenant_id), CHECK(NOT certified OR length(certification_ref)>=8));

CREATE FUNCTION c10_demo.a056_page(p_limit int,p_offset int,OUT lim int,OUT off int) LANGUAGE sql IMMUTABLE AS $f$
SELECT LEAST(GREATEST(COALESCE(p_limit,50),1),200),GREATEST(COALESCE(p_offset,0),0) $f$;
CREATE FUNCTION c10_demo.a056_stage_kind(p_business bigint,p_code text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
SELECT x->>'kind' FROM jsonb_array_elements(c10_demo.a056_cfg(p_business)->'stages') x WHERE x->>'code'=p_code $f$;
CREATE FUNCTION c10_demo.a056_user_in_business(p_tenant bigint,p_business bigint,p_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
SELECT EXISTS(SELECT 1 FROM c10_demo.tenant_members WHERE tenant_id=p_tenant AND user_id=p_user AND active) OR
 EXISTS(SELECT 1 FROM c10_demo.business_members WHERE business_id=p_business AND user_id=p_user AND active AND role IN('business_owner','manager')) OR
 EXISTS(SELECT 1 FROM c10_demo.site_grants WHERE business_id=p_business AND user_id=p_user AND active) $f$;

-- ---------- leads ----------
CREATE FUNCTION c10_demo.a056_create_lead_v1(p_business bigint,p_site bigint,p_source text,p_name text,p_email text,p_phone text,p_note text,p_customer bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint;
BEGIN
 t:=c10_demo.a056_require(p_business,p_site,'lead.write');
 h:=c10_demo.a056_h(p_site::text,p_source,p_name,p_email,p_phone,p_note,p_customer::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'create_lead',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_customer IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c10_demo.a056_customers WHERE id=p_customer AND business_id=p_business AND status='active' AND c10_demo.a056_row_ok(tenant_id,business_id,site_id)) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF c10_demo.a056_txt(p_name,200) IS NULL AND p_email IS NULL AND p_phone IS NULL AND p_customer IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 INSERT INTO c10_demo.a056_leads(tenant_id,business_id,site_id,source,name,email,phone,email_norm,phone_norm,note,customer_id,request_key,created_by)
 VALUES(t,p_business,p_site,c10_demo.a056_txt(p_source,60,true),c10_demo.a056_txt(p_name,200),c10_demo.a056_txt(p_email,254),c10_demo.a056_txt(p_phone,32),c10_demo.a056_email_norm(p_email),c10_demo.a056_phone_norm(p_phone),
  c10_demo.a056_txt(p_note,2000),p_customer,p_request,c10_demo.actor_uid()) RETURNING a056_leads.id INTO id;
 PERFORM c10_demo.a056_log(t,p_business,'lead.create','lead',id,p_request);
 RETURN c10_demo.a056_done(p_business,p_request,'create_lead',h,jsonb_build_object('lead_id',id,'status','new','version',1));
END $f$;
CREATE FUNCTION c10_demo.a056_qualify_lead_v1(p_lead bigint,p_decision text,p_reason text,p_expected bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE l c10_demo.a056_leads%ROWTYPE; h text; prev jsonb; nv bigint;
BEGIN
 SELECT * INTO l FROM c10_demo.a056_leads WHERE id=p_lead FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(l.business_id,l.site_id,'lead.write',false,true);
 h:=c10_demo.a056_h(p_lead::text,p_decision,p_reason,p_expected::text);
 prev:=c10_demo.a056_idem_check(l.business_id,p_request,'qualify_lead',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_decision NOT IN('qualified','disqualified') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF l.version<>p_expected THEN RAISE EXCEPTION 'A056_STALE_LEAD'; END IF;
 IF l.status<>'new' THEN RAISE EXCEPTION 'A056_LEAD_TRANSITION'; END IF;
 IF p_decision='disqualified' AND c10_demo.a056_txt(p_reason,500) IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 UPDATE c10_demo.a056_leads SET status=p_decision,reason=c10_demo.a056_txt(p_reason,500),version=version+1 WHERE id=p_lead RETURNING version INTO nv;
 PERFORM c10_demo.a056_log(l.tenant_id,l.business_id,'lead.'||p_decision,'lead',p_lead,p_request);
 RETURN c10_demo.a056_done(l.business_id,p_request,'qualify_lead',h,jsonb_build_object('lead_id',p_lead,'status',p_decision,'version',nv));
END $f$;
CREATE FUNCTION c10_demo.a056_list_leads_v1(p_business bigint,p_status text DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE lim int; off int; tot int; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'lead.write',true); SELECT * INTO lim,off FROM c10_demo.a056_page(p_limit,p_offset);
 SELECT count(*) INTO tot FROM c10_demo.a056_leads x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id);
 SELECT COALESCE(jsonb_agg(to_jsonb(q)-'request_key'-'created_by'-'email_norm'-'phone_norm' ORDER BY q.id DESC),'[]') INTO items FROM
  (SELECT * FROM c10_demo.a056_leads x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id) ORDER BY x.id DESC LIMIT lim OFFSET off) q;
 RETURN jsonb_build_object('items',items,'total',tot,'limit',lim,'offset',off);
END $f$;

-- ---------- enquiries ----------
CREATE FUNCTION c10_demo.a056_create_enquiry_v1(p_business bigint,p_site bigint,p_channel text,p_subject text,p_body text,p_customer bigint,p_lead bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint; ref text; cn text;
BEGIN
 t:=c10_demo.a056_require(p_business,p_site,'lead.write');
 h:=c10_demo.a056_h(p_site::text,p_channel,p_subject,p_body,p_customer::text,p_lead::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'create_enquiry',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_channel NOT IN('website','ecommerce','pos','offline','phone','email','staff') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_customer IS NOT NULL THEN SELECT display_name INTO cn FROM c10_demo.a056_customers WHERE id=p_customer AND business_id=p_business AND status='active' AND c10_demo.a056_row_ok(tenant_id,business_id,site_id); IF NOT FOUND THEN RAISE EXCEPTION 'A056_INVALID'; END IF; END IF;
 IF p_lead IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c10_demo.a056_leads WHERE id=p_lead AND business_id=p_business) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 ref:='ENQ-'||upper(substr(c10_demo.a056_sha(p_business::text||p_request||clock_timestamp()::text),1,12));
 INSERT INTO c10_demo.a056_enquiries(tenant_id,business_id,site_id,channel,subject,body,customer_id,lead_id,reference,status,request_key,created_by)
 VALUES(t,p_business,p_site,p_channel,c10_demo.a056_txt(p_subject,200,true),c10_demo.a056_txt(p_body,4000),p_customer,p_lead,ref,'RECEIVED',p_request,c10_demo.actor_uid()) RETURNING a056_enquiries.id INTO id;
 IF p_customer IS NOT NULL THEN PERFORM c10_demo.a056_hist(t,p_business,p_site,p_customer,'system','in','Enquiry received: '||left(c10_demo.a056_txt(p_subject,200,true),100),'enq-'||p_request); END IF;
 PERFORM c10_demo.a056_log(t,p_business,'enquiry.create','enquiry',id,p_request);
 RETURN c10_demo.a056_done(p_business,p_request,'create_enquiry',h,jsonb_build_object('enquiry_id',id,'status','RECEIVED','reference',ref,'version',1));
END $f$;
-- consent claims captured at intake become real consent events only after staff triage links a customer; opt-out suppression wins
CREATE FUNCTION c10_demo.a056_apply_consent_claims(p_enq c10_demo.a056_enquiries,p_customer bigint,p_key text) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c10_demo_ok boolean; k text; ch text; n int:=0; st jsonb;
BEGIN
 FOR k IN SELECT jsonb_object_keys(COALESCE(p_enq.payload->'consent','{}')) LOOP
  IF k NOT IN('marketing_email','marketing_sms') OR (p_enq.payload->'consent'->>k)<>'true' THEN CONTINUE; END IF;
  ch:=CASE k WHEN 'marketing_email' THEN 'email' ELSE 'sms' END;
  st:=c10_demo.a056_consent_state(p_customer,ch,'marketing');
  IF st->>'reason'='opt_out_precedence' THEN CONTINUE; END IF;
  INSERT INTO c10_demo.a056_consent_events(tenant_id,business_id,site_id,customer_id,channel,purpose,status,source,recorded_by,request_key)
  VALUES(p_enq.tenant_id,p_enq.business_id,p_enq.site_id,p_customer,ch,'marketing','granted','intake_claim:'||p_enq.reference,c10_demo.actor_uid(),'cc-'||p_enq.id||'-'||ch||'-'||left(p_key,40)) ON CONFLICT DO NOTHING;
  n:=n+1;
 END LOOP;
 RETURN n;
END $f$;
CREATE FUNCTION c10_demo.a056_triage_enquiry_v1(p_enquiry bigint,p_action text,p_customer bigint,p_expected bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE e c10_demo.a056_enquiries%ROWTYPE; h text; prev jsonb; nv bigint; lid bigint; ns text; resp jsonb; claims int:=0; cid bigint;
BEGIN
 SELECT * INTO e FROM c10_demo.a056_enquiries WHERE id=p_enquiry FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(e.business_id,e.site_id,'enquiry.triage',false,true);
 h:=c10_demo.a056_h(p_enquiry::text,p_action,p_customer::text,p_expected::text);
 prev:=c10_demo.a056_idem_check(e.business_id,p_request,'triage_enquiry',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_action NOT IN('triage','to_lead','close') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF e.version<>p_expected THEN RAISE EXCEPTION 'A056_STALE_ENQUIRY'; END IF;
 IF e.status IN('converted','closed') OR (p_action='triage' AND e.status='triaged') THEN RAISE EXCEPTION 'A056_ENQUIRY_TRANSITION'; END IF;
 cid:=COALESCE(p_customer,e.customer_id);
 IF cid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c10_demo.a056_customers WHERE id=cid AND business_id=e.business_id AND status='active' AND c10_demo.a056_row_ok(tenant_id,business_id,site_id)) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_action='to_lead' THEN
  INSERT INTO c10_demo.a056_leads(tenant_id,business_id,site_id,source,name,email,phone,email_norm,phone_norm,note,customer_id,request_key,created_by)
  VALUES(e.tenant_id,e.business_id,e.site_id,'enquiry:'||e.channel,e.contact_name,e.contact_email,e.contact_phone,
   CASE WHEN e.contact_email IS NULL THEN NULL ELSE c10_demo.a056_email_norm(e.contact_email) END,CASE WHEN e.contact_phone IS NULL THEN NULL ELSE c10_demo.a056_phone_norm(e.contact_phone) END,
   left(COALESCE(e.subject,'')||' '||COALESCE(e.body,''),2000),cid,'lead-'||p_request,c10_demo.actor_uid()) RETURNING a056_leads.id INTO lid;
 END IF;
 IF cid IS NOT NULL AND p_action<>'close' THEN claims:=c10_demo.a056_apply_consent_claims(e,cid,p_request); END IF;
 ns:=CASE p_action WHEN 'triage' THEN 'triaged' WHEN 'to_lead' THEN 'converted' ELSE 'closed' END;
 UPDATE c10_demo.a056_enquiries SET status=ns,lead_id=COALESCE(lid,lead_id),customer_id=cid,version=version+1 WHERE id=p_enquiry RETURNING version INTO nv;
 PERFORM c10_demo.a056_log(e.tenant_id,e.business_id,'enquiry.'||p_action,'enquiry',p_enquiry,p_request,jsonb_build_object('consent_claims_applied',claims));
 resp:=jsonb_build_object('enquiry_id',p_enquiry,'status',ns,'lead_id',lid,'version',nv,'consent_claims_applied',claims);
 RETURN c10_demo.a056_done(e.business_id,p_request,'triage_enquiry',h,resp);
END $f$;
CREATE FUNCTION c10_demo.a056_list_enquiries_v1(p_business bigint,p_status text DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE lim int; off int; tot int; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'enquiry.triage',true); SELECT * INTO lim,off FROM c10_demo.a056_page(p_limit,p_offset);
 SELECT count(*) INTO tot FROM c10_demo.a056_enquiries x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id);
 SELECT COALESCE(jsonb_agg(to_jsonb(q)-'request_key'-'created_by' ORDER BY q.id DESC),'[]') INTO items FROM
  (SELECT * FROM c10_demo.a056_enquiries x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id) ORDER BY x.id DESC LIMIT lim OFFSET off) q;
 RETURN jsonb_build_object('items',items,'total',tot,'limit',lim,'offset',off);
END $f$;

-- ---------- opportunities ----------
CREATE FUNCTION c10_demo.a056_create_opportunity_v1(p_business bigint,p_site bigint,p_customer bigint,p_lead bigint,p_enquiry bigint,p_title text,p_expected_value numeric,p_expected_close date,p_owner uuid,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint; st text; cs bigint;
BEGIN
 t:=c10_demo.a056_require(p_business,p_site,'opportunity.write');
 h:=c10_demo.a056_h(p_site::text,p_customer::text,p_lead::text,p_enquiry::text,p_title,p_expected_value::text,p_expected_close::text,p_owner::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'create_opportunity',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 SELECT site_id INTO cs FROM c10_demo.a056_customers WHERE id=p_customer AND business_id=p_business AND status='active' AND c10_demo.a056_row_ok(tenant_id,business_id,site_id);
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_lead IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c10_demo.a056_leads WHERE id=p_lead AND business_id=p_business AND status IN('new','qualified')) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_enquiry IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c10_demo.a056_enquiries WHERE id=p_enquiry AND business_id=p_business) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_expected_value IS NOT NULL AND (p_expected_value<0 OR p_expected_value>100000000 OR p_expected_value<>round(p_expected_value,2)) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_owner IS NOT NULL AND NOT c10_demo.a056_user_in_business(t,p_business,p_owner) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 st:=c10_demo.a056_cfg(p_business)->'stages'->0->>'code';
 INSERT INTO c10_demo.a056_opportunities(tenant_id,business_id,site_id,customer_id,lead_id,enquiry_id,title,stage_code,expected_value,expected_close,owner_user,request_key,created_by)
 VALUES(t,p_business,p_site,p_customer,p_lead,p_enquiry,c10_demo.a056_txt(p_title,200,true),st,p_expected_value,p_expected_close,p_owner,p_request,c10_demo.actor_uid()) RETURNING a056_opportunities.id INTO id;
 INSERT INTO c10_demo.a056_opp_stage_log(tenant_id,business_id,opportunity_id,from_stage,to_stage,actor,reason,request_key) VALUES(t,p_business,id,NULL,st,c10_demo.actor_uid(),'created','os-'||p_request);
 IF p_lead IS NOT NULL THEN UPDATE c10_demo.a056_leads SET status='converted',customer_id=COALESCE(customer_id,p_customer),version=version+1 WHERE id=p_lead; END IF;
 IF p_enquiry IS NOT NULL THEN UPDATE c10_demo.a056_enquiries SET status='converted',version=version+1 WHERE id=p_enquiry AND status IN('RECEIVED','DRAFT','triaged'); END IF;
 PERFORM c10_demo.a056_hist(t,p_business,p_site,p_customer,'system','internal','Opportunity created: '||left(p_title,120),'op-'||p_request,p_lead,id);
 PERFORM c10_demo.a056_log(t,p_business,'opportunity.create','opportunity',id,p_request);
 RETURN c10_demo.a056_done(p_business,p_request,'create_opportunity',h,jsonb_build_object('opportunity_id',id,'stage',st,'version',1));
END $f$;
CREATE FUNCTION c10_demo.a056_move_opportunity_stage_v1(p_opp bigint,p_stage text,p_expected bigint,p_reason text,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE o c10_demo.a056_opportunities%ROWTYPE; h text; prev jsonb; nv bigint; kind text; appr boolean; ns text;
BEGIN
 SELECT * INTO o FROM c10_demo.a056_opportunities WHERE id=p_opp FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(o.business_id,o.site_id,'opportunity.stage',false,true);
 h:=c10_demo.a056_h(p_opp::text,p_stage,p_expected::text,p_reason);
 prev:=c10_demo.a056_idem_check(o.business_id,p_request,'move_stage',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 kind:=c10_demo.a056_stage_kind(o.business_id,p_stage);
 IF kind IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF o.version<>p_expected THEN RAISE EXCEPTION 'A056_STALE_OPPORTUNITY'; END IF;
 IF o.status<>'open' THEN RAISE EXCEPTION 'A056_OPP_CLOSED'; END IF;
 IF p_stage=o.stage_code THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 SELECT COALESCE((x->>'approval')::boolean,false) INTO appr FROM jsonb_array_elements(c10_demo.a056_cfg(o.business_id)->'stages') x WHERE x->>'code'=p_stage;
 IF appr AND NOT c10_demo.a056_authz(o.tenant_id,o.business_id,NULL,'quote.approve') THEN RAISE EXCEPTION 'A056_STAGE_APPROVAL_REQUIRED'; END IF;
 IF kind='won' AND NOT EXISTS(SELECT 1 FROM c10_demo.a056_quote_versions v JOIN c10_demo.a056_quotations q ON q.id=v.quotation_id WHERE q.opportunity_id=o.id AND v.status='converted') THEN RAISE EXCEPTION 'A056_WON_REQUIRES_ORDER'; END IF;
 IF kind='lost' AND c10_demo.a056_txt(p_reason,500) IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 ns:=CASE kind WHEN 'open' THEN 'open' ELSE kind END;
 UPDATE c10_demo.a056_opportunities SET stage_code=p_stage,status=ns,version=version+1,closed_at=CASE WHEN ns<>'open' THEN now() END WHERE id=p_opp RETURNING version INTO nv;
 INSERT INTO c10_demo.a056_opp_stage_log(tenant_id,business_id,opportunity_id,from_stage,to_stage,actor,reason,request_key) VALUES(o.tenant_id,o.business_id,o.id,o.stage_code,p_stage,c10_demo.actor_uid(),c10_demo.a056_txt(p_reason,500),'os-'||p_request);
 PERFORM c10_demo.a056_hist(o.tenant_id,o.business_id,o.site_id,o.customer_id,'system','internal','Stage '||o.stage_code||' -> '||p_stage,'ms-'||p_request,o.lead_id,o.id);
 PERFORM c10_demo.a056_log(o.tenant_id,o.business_id,'opportunity.stage','opportunity',p_opp,p_request,jsonb_build_object('from',o.stage_code,'to',p_stage));
 RETURN c10_demo.a056_done(o.business_id,p_request,'move_stage',h,jsonb_build_object('opportunity_id',p_opp,'stage',p_stage,'status',ns,'version',nv));
END $f$;
CREATE FUNCTION c10_demo.a056_list_opportunities_v1(p_business bigint,p_stage text DEFAULT NULL,p_status text DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE lim int; off int; tot int; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'opportunity.write',true); SELECT * INTO lim,off FROM c10_demo.a056_page(p_limit,p_offset);
 SELECT count(*) INTO tot FROM c10_demo.a056_opportunities x WHERE x.business_id=p_business AND (p_stage IS NULL OR x.stage_code=p_stage) AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id);
 SELECT COALESCE(jsonb_agg(to_jsonb(q)-'request_key'-'created_by' ORDER BY q.id DESC),'[]') INTO items FROM
  (SELECT * FROM c10_demo.a056_opportunities x WHERE x.business_id=p_business AND (p_stage IS NULL OR x.stage_code=p_stage) AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id) ORDER BY x.id DESC LIMIT lim OFFSET off) q;
 RETURN jsonb_build_object('items',items,'total',tot,'limit',lim,'offset',off);
END $f$;
CREATE FUNCTION c10_demo.a056_read_pipeline_v1(p_business bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'report.read',true);
 RETURN jsonb_build_object('stages',(SELECT jsonb_agg(jsonb_build_object('code',s->>'code','label',s->>'label','kind',s->>'kind',
   'count',(SELECT count(*) FROM c10_demo.a056_opportunities o WHERE o.business_id=p_business AND o.stage_code=s->>'code' AND c10_demo.a056_row_ok(o.tenant_id,o.business_id,o.site_id)),
   'value_advisory',(SELECT sum(o.expected_value) FROM c10_demo.a056_opportunities o WHERE o.business_id=p_business AND o.stage_code=s->>'code' AND c10_demo.a056_row_ok(o.tenant_id,o.business_id,o.site_id)))
   ORDER BY ord) FROM jsonb_array_elements(c10_demo.a056_cfg(p_business)->'stages') WITH ORDINALITY a(s,ord)),
  'note','Values are advisory expected values entered by staff, not revenue; null = no value entered.');
END $f$;

-- ---------- quotations ----------
CREATE FUNCTION c10_demo.a056_write_quote_lines(p_t bigint,p_b bigint,p_version bigint,p_lines jsonb,OUT total numeric,OUT maxdisc numeric)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE l jsonb; n int:=0; q numeric; u numeric; d numeric; lt numeric; it bigint;
BEGIN
 IF p_lines IS NULL OR jsonb_typeof(p_lines)<>'array' OR jsonb_array_length(p_lines) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 total:=0; maxdisc:=0;
 FOR l IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
  n:=n+1;
  IF jsonb_typeof(l)<>'object' THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
  BEGIN q:=(l->>'quantity')::numeric; u:=(l->>'unit_price')::numeric; d:=COALESCE((l->>'discount_pct')::numeric,0); it:=(l->>'item_id')::bigint;
  EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'A056_INVALID'; END;
  IF q IS NULL OR u IS NULL OR q<=0 OR q>1000000 OR q<>round(q,3) OR u<0 OR u>100000000 OR u<>round(u,2) OR d<0 OR d>100 OR d<>round(d,2) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
  IF it IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c10_demo.items WHERE id=it AND tenant_id=p_t AND business_id=p_b) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
  lt:=round(q*u*(1-d/100),2);
  INSERT INTO c10_demo.a056_quote_lines(tenant_id,business_id,version_id,line_no,description,item_id,quantity,unit_price,discount_pct,line_total)
  VALUES(p_t,p_b,p_version,n,c10_demo.a056_txt(l->>'description',200,true),it,q,u,d,lt);
  total:=total+lt; maxdisc:=GREATEST(maxdisc,d);
 END LOOP;
 IF total>100000000000 THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
END $f$;
CREATE FUNCTION c10_demo.a056_needs_approval(p_business bigint,p_total numeric,p_maxdisc numeric) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
SELECT COALESCE(p_maxdisc>(c.a->>'discount_pct_over')::numeric,false) OR COALESCE(p_total>(c.a->>'total_over')::numeric,false) FROM (SELECT c10_demo.a056_cfg(p_business)->'approval' a) c $f$;
CREATE FUNCTION c10_demo.a056_create_quotation_v1(p_opp bigint,p_lines jsonb,p_valid_until date,p_notes text,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE o c10_demo.a056_opportunities%ROWTYPE; h text; prev jsonb; qid bigint; vid bigint; tot numeric; md numeric; ra boolean; qn text;
BEGIN
 SELECT * INTO o FROM c10_demo.a056_opportunities WHERE id=p_opp FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(o.business_id,o.site_id,'quote.write',false,true);
 h:=c10_demo.a056_h(p_opp::text,p_lines::text,p_valid_until::text,p_notes);
 prev:=c10_demo.a056_idem_check(o.business_id,p_request,'create_quotation',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF o.status<>'open' THEN RAISE EXCEPTION 'A056_OPP_CLOSED'; END IF;
 IF p_valid_until IS NOT NULL AND p_valid_until<current_date THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 INSERT INTO c10_demo.a056_quotations(tenant_id,business_id,site_id,opportunity_id,customer_id,request_key,created_by) VALUES(o.tenant_id,o.business_id,o.site_id,o.id,o.customer_id,p_request,c10_demo.actor_uid()) RETURNING a056_quotations.id INTO qid;
 qn:='Q-'||o.business_id||'-'||lpad(qid::text,6,'0'); UPDATE c10_demo.a056_quotations SET quote_no=qn WHERE id=qid;
 INSERT INTO c10_demo.a056_quote_versions(tenant_id,business_id,quotation_id,version_no,total,max_discount_pct,requires_approval,valid_until,notes,created_by)
 VALUES(o.tenant_id,o.business_id,qid,1,0,0,false,p_valid_until,c10_demo.a056_txt(p_notes,2000),c10_demo.actor_uid()) RETURNING id INTO vid;
 SELECT * INTO tot,md FROM c10_demo.a056_write_quote_lines(o.tenant_id,o.business_id,vid,p_lines);
 ra:=c10_demo.a056_needs_approval(o.business_id,tot,md);
 UPDATE c10_demo.a056_quote_versions SET total=tot,max_discount_pct=md,requires_approval=ra WHERE id=vid;
 PERFORM c10_demo.a056_log(o.tenant_id,o.business_id,'quote.create','quotation',qid,p_request,jsonb_build_object('total',tot));
 RETURN c10_demo.a056_done(o.business_id,p_request,'create_quotation',h,jsonb_build_object('quotation_id',qid,'quote_no',qn,'version_no',1,'total',tot,'requires_approval',ra,'status','draft'));
END $f$;
CREATE FUNCTION c10_demo.a056_revise_quotation_v1(p_quotation bigint,p_lines jsonb,p_valid_until date,p_notes text,p_expected_version int,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE q c10_demo.a056_quotations%ROWTYPE; cv c10_demo.a056_quote_versions%ROWTYPE; h text; prev jsonb; vid bigint; tot numeric; md numeric; ra boolean; nv int;
BEGIN
 SELECT * INTO q FROM c10_demo.a056_quotations WHERE id=p_quotation FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(q.business_id,q.site_id,'quote.write',false,true);
 h:=c10_demo.a056_h(p_quotation::text,p_lines::text,p_valid_until::text,p_notes,p_expected_version::text);
 prev:=c10_demo.a056_idem_check(q.business_id,p_request,'revise_quotation',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF q.current_version<>p_expected_version THEN RAISE EXCEPTION 'A056_STALE_QUOTATION'; END IF;
 SELECT * INTO cv FROM c10_demo.a056_quote_versions WHERE quotation_id=q.id AND version_no=q.current_version;
 IF cv.status IN('accepted','converted') THEN RAISE EXCEPTION 'A056_QUOTE_LOCKED'; END IF;
 IF p_valid_until IS NOT NULL AND p_valid_until<current_date THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 nv:=q.current_version+1;
 UPDATE c10_demo.a056_quote_versions SET status='superseded' WHERE id=cv.id;
 INSERT INTO c10_demo.a056_quote_versions(tenant_id,business_id,quotation_id,version_no,total,max_discount_pct,requires_approval,valid_until,notes,created_by)
 VALUES(q.tenant_id,q.business_id,q.id,nv,0,0,false,p_valid_until,c10_demo.a056_txt(p_notes,2000),c10_demo.actor_uid()) RETURNING id INTO vid;
 SELECT * INTO tot,md FROM c10_demo.a056_write_quote_lines(q.tenant_id,q.business_id,vid,p_lines);
 ra:=c10_demo.a056_needs_approval(q.business_id,tot,md);
 UPDATE c10_demo.a056_quote_versions SET total=tot,max_discount_pct=md,requires_approval=ra WHERE id=vid;
 UPDATE c10_demo.a056_quotations SET current_version=nv,version=version+1 WHERE id=q.id;
 PERFORM c10_demo.a056_log(q.tenant_id,q.business_id,'quote.revise','quotation',q.id,p_request,jsonb_build_object('version_no',nv,'total',tot));
 RETURN c10_demo.a056_done(q.business_id,p_request,'revise_quotation',h,jsonb_build_object('quotation_id',q.id,'version_no',nv,'total',tot,'requires_approval',ra,'status','draft'));
END $f$;
CREATE FUNCTION c10_demo.a056_decide_quotation_v1(p_quotation bigint,p_version_no int,p_decision text,p_note text,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE q c10_demo.a056_quotations%ROWTYPE; v c10_demo.a056_quote_versions%ROWTYPE; h text; prev jsonb; ns text; act text;
BEGIN
 SELECT * INTO q FROM c10_demo.a056_quotations WHERE id=p_quotation FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 act:=CASE WHEN p_decision IN('approve','reject') THEN 'quote.approve' ELSE 'quote.write' END;
 PERFORM c10_demo.a056_require(q.business_id,q.site_id,act,false,true);
 h:=c10_demo.a056_h(p_quotation::text,p_version_no::text,p_decision,p_note);
 prev:=c10_demo.a056_idem_check(q.business_id,p_request,'decide_quotation',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_decision NOT IN('submit','approve','reject','send','accept','decline') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_version_no<>q.current_version THEN RAISE EXCEPTION 'A056_STALE_QUOTATION'; END IF;
 SELECT * INTO v FROM c10_demo.a056_quote_versions WHERE quotation_id=q.id AND version_no=p_version_no FOR UPDATE;
 ns:=CASE WHEN p_decision='submit' AND v.status='draft' THEN CASE WHEN v.requires_approval THEN 'pending_approval' ELSE 'approved' END
  WHEN p_decision='approve' AND v.status='pending_approval' THEN 'approved'
  WHEN p_decision='reject' AND v.status='pending_approval' THEN 'rejected'
  WHEN p_decision='send' AND v.status='approved' THEN 'sent'
  WHEN p_decision='accept' AND v.status='sent' THEN 'accepted'
  WHEN p_decision='decline' AND v.status='sent' THEN 'declined' END;
 IF ns IS NULL THEN RAISE EXCEPTION 'A056_QUOTE_TRANSITION'; END IF;
 IF p_decision='approve' AND v.created_by=c10_demo.actor_uid() THEN RAISE EXCEPTION 'A056_SELF_APPROVAL'; END IF;
 IF p_decision IN('reject','decline') AND c10_demo.a056_txt(p_note,500) IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_decision IN('send','accept') AND v.valid_until IS NOT NULL AND v.valid_until<current_date THEN RAISE EXCEPTION 'A056_QUOTE_EXPIRED'; END IF;
 UPDATE c10_demo.a056_quote_versions SET status=ns,decided_by=CASE WHEN p_decision IN('approve','reject') THEN c10_demo.actor_uid() ELSE decided_by END,
  decided_at=CASE WHEN p_decision IN('approve','reject') THEN now() ELSE decided_at END,decision_note=COALESCE(c10_demo.a056_txt(p_note,500),decision_note) WHERE id=v.id;
 UPDATE c10_demo.a056_quotations SET version=version+1 WHERE id=q.id;
 PERFORM c10_demo.a056_hist(q.tenant_id,q.business_id,q.site_id,q.customer_id,'system',CASE WHEN p_decision IN('send') THEN 'out' WHEN p_decision IN('accept','decline') THEN 'in' ELSE 'internal' END,
  'Quotation '||q.quote_no||' v'||p_version_no||' '||ns,'qd-'||p_request,NULL,q.opportunity_id);
 PERFORM c10_demo.a056_log(q.tenant_id,q.business_id,'quote.'||p_decision,'quotation',q.id,p_request,jsonb_build_object('version_no',p_version_no,'status',ns));
 RETURN c10_demo.a056_done(q.business_id,p_request,'decide_quotation',h,jsonb_build_object('quotation_id',q.id,'version_no',p_version_no,'status',ns));
END $f$;
CREATE FUNCTION c10_demo.a056_quote_json(q c10_demo.a056_quotations,p_lines boolean DEFAULT true) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
SELECT jsonb_build_object('id',q.id,'quote_no',q.quote_no,'opportunity_id',q.opportunity_id,'customer_id',q.customer_id,'site_id',q.site_id,'current_version',q.current_version,
 'status',(SELECT status FROM c10_demo.a056_quote_versions WHERE quotation_id=q.id AND version_no=q.current_version),
 'total',(SELECT total FROM c10_demo.a056_quote_versions WHERE quotation_id=q.id AND version_no=q.current_version),
 'version',q.version,'created_at',q.created_at) ||
 CASE WHEN p_lines THEN jsonb_build_object('versions',COALESCE((SELECT jsonb_agg(jsonb_build_object('version_no',v.version_no,'status',v.status,'total',v.total,'requires_approval',v.requires_approval,
   'max_discount_pct',v.max_discount_pct,'valid_until',v.valid_until,'notes',v.notes,'created_by',v.created_by,'decided_by',v.decided_by,'decided_at',v.decided_at,'decision_note',v.decision_note,
   'lines',(SELECT COALESCE(jsonb_agg(jsonb_build_object('line_no',l.line_no,'description',l.description,'item_id',l.item_id,'quantity',l.quantity,'unit_price',l.unit_price,'discount_pct',l.discount_pct,'line_total',l.line_total) ORDER BY l.line_no),'[]')
     FROM c10_demo.a056_quote_lines l WHERE l.version_id=v.id)) ORDER BY v.version_no) FROM c10_demo.a056_quote_versions v WHERE v.quotation_id=q.id),'[]')) ELSE '{}'::jsonb END $f$;
CREATE FUNCTION c10_demo.a056_read_quotation_v1(p_quotation bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE q c10_demo.a056_quotations%ROWTYPE;
BEGIN
 SELECT * INTO q FROM c10_demo.a056_quotations WHERE id=p_quotation;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(q.business_id,q.site_id,'quote.write',false,true);
 IF NOT c10_demo.a056_row_ok(q.tenant_id,q.business_id,q.site_id) THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 RETURN jsonb_build_object('quotation',c10_demo.a056_quote_json(q,false),'versions',c10_demo.a056_quote_json(q,true)->'versions');
END $f$;
CREATE FUNCTION c10_demo.a056_list_quotations_v1(p_business bigint,p_status text DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE lim int; off int; tot int; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'quote.write',true); SELECT * INTO lim,off FROM c10_demo.a056_page(p_limit,p_offset);
 SELECT count(*),COALESCE(jsonb_agg(c10_demo.a056_quote_json(q,false) ORDER BY q.id DESC) FILTER (WHERE rn>off AND rn<=off+lim),'[]') INTO tot,items FROM
  (SELECT x.*,row_number() OVER (ORDER BY x.id DESC) rn FROM c10_demo.a056_quotations x WHERE x.business_id=p_business AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)
   AND (p_status IS NULL OR p_status=(SELECT status FROM c10_demo.a056_quote_versions WHERE quotation_id=x.id AND version_no=x.current_version))) q;
 RETURN jsonb_build_object('items',items,'total',tot,'limit',lim,'offset',off);
END $f$;

-- ---------- sales/order integration: ONLY through A049 contracts ----------
CREATE FUNCTION c10_demo.a056_convert_core(p_quotation bigint,p_version_no int,p_location bigint,p_request text,p_test boolean) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE q c10_demo.a056_quotations%ROWTYPE; v c10_demo.a056_quote_versions%ROWTYPE; loc c10_demo.stock_locations%ROWTYPE; h text; prev jsonb; l c10_demo.a056_quote_lines%ROWTYPE;
 net numeric; r jsonb; oid bigint; lid bigint; links jsonb:='[]'; act text:=CASE WHEN p_test THEN 'create_order_test' ELSE 'convert_quote' END;
BEGIN
 SELECT * INTO q FROM c10_demo.a056_quotations WHERE id=p_quotation FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(q.business_id,q.site_id,'quote.convert',false,true);
 h:=c10_demo.a056_h(p_quotation::text,p_version_no::text,p_location::text);
 prev:=c10_demo.a056_idem_check(q.business_id,p_request,act,h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 SELECT * INTO v FROM c10_demo.a056_quote_versions WHERE quotation_id=q.id AND version_no=p_version_no FOR UPDATE;
 IF NOT FOUND OR p_version_no<>q.current_version THEN RAISE EXCEPTION 'A056_STALE_QUOTATION'; END IF;
 IF v.status<>'accepted' THEN RAISE EXCEPTION 'A056_QUOTE_NOT_ACCEPTED'; END IF;
 SELECT * INTO loc FROM c10_demo.stock_locations WHERE id=p_location AND business_id=q.business_id AND tenant_id=q.tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF EXISTS(SELECT 1 FROM c10_demo.a056_quote_lines WHERE version_id=v.id AND item_id IS NULL) THEN RAISE EXCEPTION 'A056_LINE_UNMAPPED'; END IF;
 FOR l IN SELECT * FROM c10_demo.a056_quote_lines WHERE version_id=v.id ORDER BY line_no LOOP
  net:=round(l.unit_price*(1-l.discount_pct/100),2);
  IF NOT p_test THEN
   BEGIN
    r:=c10_demo.create_operation_order_v1(q.business_id,p_location,l.item_id,'sale_issue',l.quantity,net,left('A056:'||q.quote_no||':v'||p_version_no||':L'||l.line_no,120),
     'a056q'||q.id||'v'||p_version_no||'l'||l.line_no||left(c10_demo.a056_sha(p_request),12));
   EXCEPTION WHEN raise_exception THEN RAISE EXCEPTION 'A056_ORDER_ADAPTER_REJECTED:%',SQLERRM; END;
   oid:=(r->>'order_id')::bigint;
  ELSE oid:=NULL; END IF;
  INSERT INTO c10_demo.a056_order_links(tenant_id,business_id,site_id,customer_id,quotation_id,version_no,line_no,a049_order_id,adapter,quantity,net_unit_price,request_key,created_by)
  VALUES(q.tenant_id,q.business_id,loc.site_id,q.customer_id,q.id,p_version_no,l.line_no,oid,CASE WHEN p_test THEN 'TEST_ADAPTER' ELSE 'A049_CANONICAL' END,l.quantity,net,p_request,c10_demo.actor_uid()) RETURNING id INTO lid;
  links:=links||jsonb_build_object('link_id',lid,'line_no',l.line_no,'a049_order_id',oid,'status',CASE WHEN p_test THEN 'test_adapter_draft' ELSE 'draft' END);
 END LOOP;
 UPDATE c10_demo.a056_quote_versions SET status='converted' WHERE id=v.id;
 UPDATE c10_demo.a056_quotations SET version=version+1 WHERE id=q.id;
 PERFORM c10_demo.a056_hist(q.tenant_id,q.business_id,loc.site_id,q.customer_id,'system','internal','Order request(s) created from '||q.quote_no||' v'||p_version_no||CASE WHEN p_test THEN ' [TEST ADAPTER]' ELSE ' via A049 (draft)' END,'cv-'||p_request,NULL,q.opportunity_id);
 PERFORM c10_demo.a056_log(q.tenant_id,q.business_id,CASE WHEN p_test THEN 'order.test_adapter' ELSE 'order.convert' END,'quotation',q.id,p_request,jsonb_build_object('lines',jsonb_array_length(links)));
 RETURN c10_demo.a056_done(q.business_id,p_request,act,h,jsonb_build_object('quotation_id',q.id,'links',links,'adapter',CASE WHEN p_test THEN 'TEST_ADAPTER' ELSE 'A049_CANONICAL' END,
  'note','A049 orders are drafts; confirmation/posting stay in A049. No revenue, stock or finance posting by CRM.'));
END $f$;
CREATE FUNCTION c10_demo.a056_convert_quote_to_order_v1(p_quotation bigint,p_version_no int,p_location bigint,p_request text) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$ SELECT c10_demo.a056_convert_core(p_quotation,p_version_no,p_location,p_request,false) $f$;
-- ISOLATED TEST ADAPTER: records links without any A049 order. Only usable when the A049 contract is absent (or simulated absent in disposable tests).
CREATE FUNCTION c10_demo.a056_TEST_ADAPTER_create_order_v1(p_quotation bigint,p_version_no int,p_location bigint,p_request text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
BEGIN
 IF current_database() !~ '^core10_a048_(ci|local)' THEN RAISE EXCEPTION 'A056_TEST_ADAPTER_DISPOSABLE_ONLY'; END IF;
 IF to_regprocedure('c10_demo.create_operation_order_v1(bigint,bigint,bigint,text,numeric,numeric,text,text)') IS NOT NULL AND COALESCE(current_setting('a056.simulate_a049_missing',true),'')<>'on'
 THEN RAISE EXCEPTION 'A056_USE_CANONICAL_ADAPTER'; END IF;
 RETURN c10_demo.a056_convert_core(p_quotation,p_version_no,p_location,p_request,true);
END $f$;
CREATE FUNCTION c10_demo.a056_order_status(p_business bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
BEGIN
 RETURN c10_demo.read_operation_overview_v1(p_business);
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $f$;
CREATE FUNCTION c10_demo.a056_read_order_links_v1(p_business bigint,p_customer bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE ov jsonb; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'customer.read',true);
 ov:=c10_demo.a056_order_status(p_business);
 SELECT COALESCE(jsonb_agg(jsonb_build_object('link_id',k.id,'quotation_id',k.quotation_id,'version_no',k.version_no,'line_no',k.line_no,'customer_id',k.customer_id,'adapter',k.adapter,'a049_order_id',k.a049_order_id,
  'order_status',o->>'status','fulfilment',CASE WHEN k.adapter='TEST_ADAPTER' THEN 'unavailable' WHEN o IS NULL THEN 'unavailable' ELSE o->>'status' END,
  'estimate_total',round(k.quantity*k.net_unit_price,2),'created_at',k.created_at) ORDER BY k.id DESC),'[]') INTO items
 FROM c10_demo.a056_order_links k LEFT JOIN LATERAL (SELECT x AS o FROM jsonb_array_elements(COALESCE(ov->'items','[]')) x WHERE (x->>'id')::bigint=k.a049_order_id LIMIT 1) j ON true
 WHERE k.business_id=p_business AND (p_customer IS NULL OR k.customer_id=p_customer) AND c10_demo.a056_row_ok(k.tenant_id,k.business_id,k.site_id);
 RETURN jsonb_build_object('items',items,'a049_overview_available',ov IS NOT NULL,'note','fulfilment is read through A049 read_operation_overview_v1; unavailable when not readable');
END $f$;
CREATE FUNCTION c10_demo.a056_read_purchase_history_v1(p_customer bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c c10_demo.a056_customers%ROWTYPE; r jsonb; posted jsonb;
BEGIN
 SELECT * INTO c FROM c10_demo.a056_customers WHERE id=p_customer;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(c.business_id,c.site_id,'customer.read',false,true);
 r:=c10_demo.a056_read_order_links_v1(c.business_id,p_customer);
 SELECT COALESCE(jsonb_agg(x),'[]') INTO posted FROM jsonb_array_elements(r->'items') x WHERE x->>'fulfilment'='posted';
 RETURN jsonb_build_object('customer_id',p_customer,'orders',r->'items','posted_count',jsonb_array_length(posted),
  'estimate_total_advisory',(SELECT sum((x->>'estimate_total')::numeric) FROM jsonb_array_elements(posted) x),
  'first_purchase',(SELECT min(k.created_at) FROM c10_demo.a056_order_links k WHERE k.customer_id=p_customer AND (r->'items') @> jsonb_build_array(jsonb_build_object('link_id',k.id,'fulfilment','posted'))),
  'last_purchase',(SELECT max(k.created_at) FROM c10_demo.a056_order_links k WHERE k.customer_id=p_customer AND (r->'items') @> jsonb_build_array(jsonb_build_object('link_id',k.id,'fulfilment','posted'))),
  'certified',false,'note','Estimates from quoted values; not revenue, tax or COGS. Orders count as purchases only when A049 status is posted.');
END $f$;

-- ---------- finance boundary: certified read models only ----------
CREATE FUNCTION c10_demo.a056_register_finance_source_v1(p_business bigint,p_read_fn text,p_certification_ref text,p_certified boolean,p_expected bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; nv bigint; proc regprocedure; nm text;
BEGIN
 t:=c10_demo.a056_require(p_business,NULL,'finance.register');
 h:=c10_demo.a056_h(p_read_fn,p_certification_ref,p_certified::text,p_expected::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'register_finance',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_read_fn IS NULL OR p_read_fn !~ '^c10_demo\.(read_[a-z0-9_]+_v1|a056_test_finance_[a-z0-9_]+)$' OR p_certified IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 proc:=to_regprocedure(p_read_fn||'(bigint,bigint)');
 IF proc IS NULL THEN RAISE EXCEPTION 'A056_FINANCE_FN_MISSING'; END IF;
 IF p_certified AND (c10_demo.a056_txt(p_certification_ref,200) IS NULL OR length(p_certification_ref)<8) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 INSERT INTO c10_demo.a056_finance_sources(business_id,tenant_id,read_fn,certification_ref,certified,version,changed_by) VALUES(p_business,t,p_read_fn,c10_demo.a056_txt(p_certification_ref,200),false,0,c10_demo.actor_uid()) ON CONFLICT DO NOTHING;
 UPDATE c10_demo.a056_finance_sources SET read_fn=p_read_fn,certification_ref=c10_demo.a056_txt(p_certification_ref,200),certified=p_certified,version=version+1,changed_by=c10_demo.actor_uid(),changed_at=now()
  WHERE business_id=p_business AND version=p_expected RETURNING version INTO nv;
 IF nv IS NULL THEN RAISE EXCEPTION 'A056_STALE_FINANCE_SOURCE'; END IF;
 PERFORM c10_demo.a056_log(t,p_business,'finance.register','finance_source',p_business,p_request,jsonb_build_object('fn',p_read_fn,'certified',p_certified));
 RETURN c10_demo.a056_done(p_business,p_request,'register_finance',h,jsonb_build_object('business_id',p_business,'version',nv,'certified',p_certified));
END $f$;
CREATE FUNCTION c10_demo.a056_read_customer_finance_v1(p_customer bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c c10_demo.a056_customers%ROWTYPE; s c10_demo.a056_finance_sources%ROWTYPE; r jsonb; base jsonb;
BEGIN
 SELECT * INTO c FROM c10_demo.a056_customers WHERE id=p_customer;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(c.business_id,c.site_id,'finance.read',false,true);
 base:=jsonb_build_object('customer_id',p_customer,'balance_due',NULL,'payment_status',NULL,'invoices_status',NULL);
 SELECT * INTO s FROM c10_demo.a056_finance_sources WHERE business_id=c.business_id;
 IF NOT FOUND THEN RETURN base||jsonb_build_object('status','NOT_CERTIFIED','reason','no_certified_finance_read_model_registered','source',NULL); END IF;
 IF NOT s.certified THEN RETURN base||jsonb_build_object('status','NOT_CERTIFIED','reason','finance_read_model_not_certified','source',s.read_fn); END IF;
 BEGIN
  EXECUTE format('SELECT %s($1,$2)',to_regprocedure(s.read_fn||'(bigint,bigint)')::regproc::text) INTO r USING c.business_id,p_customer;
 EXCEPTION WHEN OTHERS THEN RETURN base||jsonb_build_object('status','UNAVAILABLE','reason','finance_read_failed','source',s.read_fn); END;
 IF r IS NULL OR jsonb_typeof(r)<>'object' OR (r ? 'balance_due' AND jsonb_typeof(r->'balance_due') NOT IN('number','null')) OR
    (r->>'payment_status') IS NOT NULL AND (r->>'payment_status') NOT IN('paid','partially_paid','unpaid','overdue','unknown')
 THEN RETURN base||jsonb_build_object('status','UNAVAILABLE','reason','invalid_finance_response','source',s.read_fn); END IF;
 RETURN jsonb_build_object('customer_id',p_customer,'status','CERTIFIED','balance_due',r->'balance_due','payment_status',r->'payment_status','invoices_status',r->'invoices_status',
  'as_of',r->'as_of','source',s.read_fn,'certification_ref',s.certification_ref,'test_source',s.read_fn LIKE 'c10_demo.a056_test_finance%');
END $f$;

-- ---------- follow-ups ----------
CREATE FUNCTION c10_demo.a056_create_followup_v1(p_business bigint,p_site bigint,p_customer bigint,p_opportunity bigint,p_ticket bigint,p_due_at timestamptz,p_note text,p_assignee uuid,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint; cid bigint:=p_customer;
BEGIN
 t:=c10_demo.a056_require(p_business,p_site,'followup.write');
 h:=c10_demo.a056_h(p_site::text,p_customer::text,p_opportunity::text,p_ticket::text,p_due_at::text,p_note,p_assignee::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'create_followup',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_due_at IS NULL OR p_due_at>now()+interval '5 years' THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_opportunity IS NOT NULL THEN SELECT customer_id INTO cid FROM c10_demo.a056_opportunities WHERE id=p_opportunity AND business_id=p_business; IF NOT FOUND OR (p_customer IS NOT NULL AND p_customer<>cid) THEN RAISE EXCEPTION 'A056_INVALID'; END IF; END IF;
 IF p_ticket IS NOT NULL THEN SELECT customer_id INTO cid FROM c10_demo.a056_tickets WHERE id=p_ticket AND business_id=p_business; IF NOT FOUND OR (p_customer IS NOT NULL AND p_customer<>cid) THEN RAISE EXCEPTION 'A056_INVALID'; END IF; END IF;
 IF cid IS NULL OR NOT EXISTS(SELECT 1 FROM c10_demo.a056_customers WHERE id=cid AND business_id=p_business AND status='active' AND c10_demo.a056_row_ok(tenant_id,business_id,site_id)) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_assignee IS NOT NULL AND NOT c10_demo.a056_user_in_business(t,p_business,p_assignee) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 INSERT INTO c10_demo.a056_followups(tenant_id,business_id,site_id,customer_id,opportunity_id,ticket_id,due_at,note,assignee,request_key,created_by)
 VALUES(t,p_business,p_site,cid,p_opportunity,p_ticket,p_due_at,c10_demo.a056_txt(p_note,1000),p_assignee,p_request,c10_demo.actor_uid()) RETURNING a056_followups.id INTO id;
 PERFORM c10_demo.a056_log(t,p_business,'followup.create','followup',id,p_request);
 RETURN c10_demo.a056_done(p_business,p_request,'create_followup',h,jsonb_build_object('followup_id',id,'version',1));
END $f$;
CREATE FUNCTION c10_demo.a056_complete_followup_v1(p_followup bigint,p_outcome text,p_note text,p_expected bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE f c10_demo.a056_followups%ROWTYPE; h text; prev jsonb; nv bigint;
BEGIN
 SELECT * INTO f FROM c10_demo.a056_followups WHERE id=p_followup FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(f.business_id,f.site_id,'followup.write',false,true);
 h:=c10_demo.a056_h(p_followup::text,p_outcome,p_note,p_expected::text);
 prev:=c10_demo.a056_idem_check(f.business_id,p_request,'complete_followup',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_outcome NOT IN('done','cancelled') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF f.version<>p_expected THEN RAISE EXCEPTION 'A056_STALE_FOLLOWUP'; END IF;
 IF f.status<>'open' THEN RAISE EXCEPTION 'A056_FOLLOWUP_TRANSITION'; END IF;
 UPDATE c10_demo.a056_followups SET status=p_outcome,outcome_note=c10_demo.a056_txt(p_note,1000),completed_at=now(),version=version+1 WHERE id=p_followup RETURNING version INTO nv;
 PERFORM c10_demo.a056_log(f.tenant_id,f.business_id,'followup.'||p_outcome,'followup',p_followup,p_request);
 RETURN c10_demo.a056_done(f.business_id,p_request,'complete_followup',h,jsonb_build_object('followup_id',p_followup,'status',p_outcome,'version',nv));
END $f$;
CREATE FUNCTION c10_demo.a056_list_followups_v1(p_business bigint,p_status text DEFAULT 'open',p_due_before timestamptz DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE lim int; off int; tot int; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'followup.write',true); SELECT * INTO lim,off FROM c10_demo.a056_page(p_limit,p_offset);
 SELECT count(*) INTO tot FROM c10_demo.a056_followups x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND (p_due_before IS NULL OR x.due_at<=p_due_before) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id);
 SELECT COALESCE(jsonb_agg(to_jsonb(q)-'request_key'-'created_by'||jsonb_build_object('overdue',q.status='open' AND q.due_at<now()) ORDER BY q.due_at),'[]') INTO items FROM
  (SELECT * FROM c10_demo.a056_followups x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND (p_due_before IS NULL OR x.due_at<=p_due_before) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id) ORDER BY x.due_at LIMIT lim OFFSET off) q;
 RETURN jsonb_build_object('items',items,'total',tot,'limit',lim,'offset',off);
END $f$;

-- ---------- support / SLA ----------
CREATE FUNCTION c10_demo.a056_create_ticket_v1(p_business bigint,p_site bigint,p_customer bigint,p_kind text,p_priority text,p_subject text,p_description text,p_order_link bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint; hrs int; due timestamptz;
BEGIN
 t:=c10_demo.a056_require(p_business,p_site,'ticket.write');
 h:=c10_demo.a056_h(p_site::text,p_customer::text,p_kind,p_priority,p_subject,p_description,p_order_link::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'create_ticket',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_kind NOT IN('complaint','service','warranty','return_request') OR p_priority NOT IN('urgent','standard','low') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF NOT EXISTS(SELECT 1 FROM c10_demo.a056_customers WHERE id=p_customer AND business_id=p_business AND status='active' AND c10_demo.a056_row_ok(tenant_id,business_id,site_id)) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_order_link IS NOT NULL AND NOT EXISTS(SELECT 1 FROM c10_demo.a056_order_links WHERE id=p_order_link AND business_id=p_business AND customer_id=p_customer) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 hrs:=(c10_demo.a056_cfg(p_business)->'sla'->>p_priority)::int; due:=now()+make_interval(hours=>hrs);
 INSERT INTO c10_demo.a056_tickets(tenant_id,business_id,site_id,customer_id,order_link_id,kind,priority,subject,description,sla_hours,sla_due_at,request_key,created_by)
 VALUES(t,p_business,p_site,p_customer,p_order_link,p_kind,p_priority,c10_demo.a056_txt(p_subject,200,true),c10_demo.a056_txt(p_description,4000),hrs,due,p_request,c10_demo.actor_uid()) RETURNING a056_tickets.id INTO id;
 INSERT INTO c10_demo.a056_ticket_events(tenant_id,business_id,ticket_id,event,actor,note) VALUES(t,p_business,id,'created',c10_demo.actor_uid(),NULL);
 PERFORM c10_demo.a056_hist(t,p_business,p_site,p_customer,'system','in','Ticket #'||id||' ('||p_kind||'): '||left(p_subject,100),'tk-'||p_request);
 PERFORM c10_demo.a056_log(t,p_business,'ticket.create','ticket',id,p_request);
 RETURN c10_demo.a056_done(p_business,p_request,'create_ticket',h,jsonb_build_object('ticket_id',id,'status','open','sla_due_at',due,'version',1,'finance_stock_effect','none'));
END $f$;
CREATE FUNCTION c10_demo.a056_update_ticket_v1(p_ticket bigint,p_action text,p_assignee uuid,p_note text,p_evidence text,p_expected bigint,p_request text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE k c10_demo.a056_tickets%ROWTYPE; h text; prev jsonb; nv bigint; ns text; act text; br boolean;
BEGIN
 SELECT * INTO k FROM c10_demo.a056_tickets WHERE id=p_ticket FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 act:=CASE WHEN p_action IN('resolve','close') THEN 'ticket.resolve' ELSE 'ticket.write' END;
 PERFORM c10_demo.a056_require(k.business_id,k.site_id,act,false,true);
 h:=c10_demo.a056_h(p_ticket::text,p_action,p_assignee::text,p_note,p_evidence,p_expected::text);
 prev:=c10_demo.a056_idem_check(k.business_id,p_request,'update_ticket',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_action NOT IN('assign','start','wait','respond','resolve','close','reopen') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF k.version<>p_expected THEN RAISE EXCEPTION 'A056_STALE_TICKET'; END IF;
 ns:=CASE
  WHEN p_action='assign' AND k.status IN('open','assigned','in_progress','waiting_customer') THEN CASE WHEN k.status='open' THEN 'assigned' ELSE k.status END
  WHEN p_action='start' AND k.status IN('open','assigned','waiting_customer') THEN 'in_progress'
  WHEN p_action='wait' AND k.status IN('open','assigned','in_progress') THEN 'waiting_customer'
  WHEN p_action='respond' AND k.status IN('open','assigned','in_progress','waiting_customer') THEN k.status
  WHEN p_action='resolve' AND k.status IN('open','assigned','in_progress','waiting_customer') THEN 'resolved'
  WHEN p_action='close' AND k.status='resolved' THEN 'closed'
  WHEN p_action='reopen' AND k.status IN('resolved','closed') THEN 'open' END;
 IF ns IS NULL THEN RAISE EXCEPTION 'A056_TICKET_TRANSITION'; END IF;
 IF p_action='assign' AND (p_assignee IS NULL OR NOT c10_demo.a056_user_in_business(k.tenant_id,k.business_id,p_assignee)) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF p_action='resolve' AND (c10_demo.a056_txt(p_note,2000) IS NULL OR c10_demo.a056_txt(p_evidence,1000) IS NULL) THEN RAISE EXCEPTION 'A056_RESOLUTION_EVIDENCE_REQUIRED'; END IF;
 IF p_action IN('respond','reopen') AND c10_demo.a056_txt(p_note,2000) IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 UPDATE c10_demo.a056_tickets SET status=ns,assignee=CASE WHEN p_action='assign' THEN p_assignee ELSE assignee END,
  first_response_at=CASE WHEN p_action IN('start','respond','resolve') AND first_response_at IS NULL THEN now() ELSE first_response_at END,
  resolved_at=CASE WHEN p_action='resolve' THEN now() WHEN p_action='reopen' THEN NULL ELSE resolved_at END,
  closed_at=CASE WHEN p_action='close' THEN now() WHEN p_action='reopen' THEN NULL ELSE closed_at END,
  resolution_note=CASE WHEN p_action='resolve' THEN c10_demo.a056_txt(p_note,2000) ELSE resolution_note END,
  resolution_evidence=CASE WHEN p_action='resolve' THEN c10_demo.a056_txt(p_evidence,1000) ELSE resolution_evidence END,
  reopen_count=reopen_count+CASE WHEN p_action='reopen' THEN 1 ELSE 0 END,version=version+1 WHERE id=p_ticket RETURNING version INTO nv;
 INSERT INTO c10_demo.a056_ticket_events(tenant_id,business_id,ticket_id,event,actor,note) VALUES(k.tenant_id,k.business_id,p_ticket,p_action,c10_demo.actor_uid(),c10_demo.a056_txt(p_note,2000));
 br:=CASE WHEN p_action='resolve' THEN now()>k.sla_due_at ELSE now()>k.sla_due_at AND ns NOT IN('resolved','closed') END;
 PERFORM c10_demo.a056_log(k.tenant_id,k.business_id,'ticket.'||p_action,'ticket',p_ticket,p_request,jsonb_build_object('status',ns));
 RETURN c10_demo.a056_done(k.business_id,p_request,'update_ticket',h,jsonb_build_object('ticket_id',p_ticket,'status',ns,'version',nv,'sla_breached',br));
END $f$;
CREATE FUNCTION c10_demo.a056_sla_state(k c10_demo.a056_tickets) RETURNS text LANGUAGE sql STABLE AS $f$
SELECT CASE WHEN k.resolved_at IS NOT NULL AND k.status IN('resolved','closed') THEN CASE WHEN k.resolved_at<=k.sla_due_at THEN 'met' ELSE 'breached' END
 WHEN now()>k.sla_due_at THEN 'breached' WHEN k.sla_due_at-now() < make_interval(hours=>k.sla_hours)*0.2 THEN 'at_risk' ELSE 'ok' END $f$;
CREATE FUNCTION c10_demo.a056_list_tickets_v1(p_business bigint,p_status text DEFAULT NULL,p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE lim int; off int; tot int; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'ticket.write',true); SELECT * INTO lim,off FROM c10_demo.a056_page(p_limit,p_offset);
 SELECT count(*) INTO tot FROM c10_demo.a056_tickets x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id);
 SELECT COALESCE(jsonb_agg(to_jsonb(q)-'request_key'-'created_by'||jsonb_build_object('sla_state',c10_demo.a056_sla_state(q)) ORDER BY q.id DESC),'[]') INTO items FROM
  (SELECT * FROM c10_demo.a056_tickets x WHERE x.business_id=p_business AND (p_status IS NULL OR x.status=p_status) AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id) ORDER BY x.id DESC LIMIT lim OFFSET off) q;
 RETURN jsonb_build_object('items',items,'total',tot,'limit',lim,'offset',off);
END $f$;
